export function getTokenCard(id: string): CardDefinition | undefined {
  return TOKEN_CARDS[id];
}

const mageCardMap = new Map<string, CardDefinition>(MAGE_CARDS.map((c) => [c.id, c]));

const getMage = (id: string): CardDefinition => {
  const card = mageCardMap.get(id);
  if (!card) throw new Error(`Unknown Mage card id: ${id}`);
  return card;
};

