function extractRandomNumber(rng?: Rng | (() => number)): number {
  if (!rng) return Math.random();
  if (typeof (rng as Rng).next === 'function') {
    return (rng as Rng).next();
  }
  return (rng as () => number)();
}

/**
 * Returns a deterministic random minion of the specified mana cost.
 * Automatically clamps negative costs to 0 and costs >10 to 10.
 * Never throws and never returns undefined.
 */
export function getRandomMinionOfCost(cost: number, rng?: Rng | (() => number)): CardDefinition {
  const clampedCost = Math.max(0, Math.min(10, Math.floor(cost)));
  const pool = MINION_POOL_BY_COST[clampedCost];
  if (!pool || pool.length === 0) {
    return TOKEN_CARDS['token-wisp'];
  }
  const r = extractRandomNumber(rng);
  const index = Math.floor(r * pool.length);
  return pool[index];
}

