export type SpellPoolType = 'frost' | 'fire' | 'arcane' | 'secret' | 'leyline' | 'highCost5' | 'highCost8' | 'druid' | 'all';

/**
 * Returns a random spell from the designated spell pool.
 */
export function getRandomSpell(poolType: SpellPoolType, rng?: Rng | (() => number)): CardDefinition {
  let pool: CardDefinition[];
  switch (poolType) {
    case 'frost':
      pool = FROST_SPELLS_POOL;
      break;
    case 'fire':
      pool = FIRE_SPELLS_POOL;
      break;
    case 'arcane':
      pool = ARCANE_SPELLS_POOL;
      break;
    case 'secret':
      pool = MAGE_SECRETS_POOL;
      break;
    case 'leyline':
      pool = LEYLINES_POOL;
      break;
    case 'highCost5':
      pool = HIGH_COST_SPELLS_5_PLUS;
      break;
    case 'highCost8':
      pool = HIGH_COST_SPELLS_8_PLUS;
      break;
    case 'druid':
      pool = DRUID_SPELLS_POOL;
      break;
    case 'all':
    default:
      pool = MAGE_CARDS.filter((c) => c.type === 'SPELL');
      break;
  }
  const r = extractRandomNumber(rng);
  const index = Math.floor(r * pool.length);
  return pool[index];
}

/**
 * Returns a random spell of exact mana cost from mage-cards.json.
 * Falls back to closest available spell if no spell of exact cost exists.
 */
export function getRandomSpellOfCost(cost: number, rng?: Rng | (() => number)): CardDefinition {
  const spells = MAGE_CARDS.filter((c) => c.type === 'SPELL');
  const exact = spells.filter((c) => c.cost === cost);
  const pool = exact.length > 0 ? exact : spells;
  const r = extractRandomNumber(rng);
  return pool[Math.floor(r * pool.length)];
}
